// 1. Get processed solution IDs (stringified, ignoring __INIT__)
const processed = new Set(
  $('Load Processed IDs').all()
    .map(i => String(i.json.solution_id || ''))
    .filter(id => id && id !== '__INIT__')
);

// 2. Collect all current solutions from API
const allSolutionItems = $('Get Current Solutions').all();
const allSolutions = [];

for (const item of allSolutionItems) {
  const data = item.json;
  if (Array.isArray(data)) {
    allSolutions.push(...data);
  } else if (Array.isArray(data?.data)) {
    allSolutions.push(...data.data);
  } else if (data && data.id) {
    allSolutions.push(data);
  }
}

// 3. Filter only solutions that haven't been completed yet
const newSolutions = allSolutions.filter(s => s && s.id && !processed.has(String(s.id)));

return newSolutions.map(s => ({
  json: {
    id: String(s.id),
    titleEn: s.titleEn || '',
    titleTh: s.titleTh || '',
    descEn: s.content?.en?.hero?.description || s.descEn || '',
    descTh: s.content?.th?.hero?.description || s.descTh || '',
    link: s.link || `/solutions/${s.id}`,
    url: `https://www.syaco.co.th${s.link || `/solutions/${s.id}`}`
  }
}));

const sol = $('Split In Batches').first().json;

// Prompt A: Bluesky (Micro <= 300 chars TH) + Dev.to (Technical Markdown for developers)
const promptA = [
  'You are a tech writer for SyaCo (enterprise software engineering firm).',
  'Create 2 content formats for the new enterprise solution described below.',
  '',
  'Solution Context:',
  `Title: ${sol.titleTh} (${sol.titleEn})`,
  `Description: ${sol.descTh}`,
  `URL: ${sol.url}`,
  '',
  'Format 1: Bluesky Post (blueskyPost)',
  '- Short, punchy, informative post in Thai strictly under 300 characters.',
  `- MUST include the exact URL: ${sol.url}`,
  '- Engaging hook for enterprise IT managers and developers.',
  '',
  'Format 2: Dev.to Article (devtoArticle)',
  '- High-quality technical guide / architectural overview in Markdown.',
  '- Title in Thai or bilingual.',
  `- Include practical problem solving and introduce the SyaCo solution with natural backlink: ${sol.url}`,
  '- Tags: 3 to 4 tags strictly alphanumeric [a-z0-9] (e.g. devops, automation, architecture, webdev).',
  '',
  'Return valid JSON only matching the schema.'
].join('\n');

const geminiBodyA = {
  contents: [{ parts: [{ text: promptA }] }],
  generationConfig: {
    temperature: 0.7,
    responseMimeType: 'application/json',
    responseSchema: {
      type: 'OBJECT',
      properties: {
        blueskyPost: { type: 'STRING' },
        devtoArticle: {
          type: 'OBJECT',
          properties: {
            title: { type: 'STRING' },
            bodyMarkdown: { type: 'STRING' },
            tags: { type: 'ARRAY', items: { type: 'STRING' } }
          },
          required: ['title', 'bodyMarkdown', 'tags']
        }
      },
      required: ['blueskyPost', 'devtoArticle']
    }
  }
};

// Prompt B: Hashnode Article + Manual Enterprise Press Release / Tech Article
const promptB = [
  'You are a senior tech evangelist for SyaCo.',
  'Create 2 long-form technical content pieces for this new enterprise solution:',
  '',
  'Solution Context:',
  `Title: ${sol.titleTh} (${sol.titleEn})`,
  `Description: ${sol.descTh}`,
  `URL: ${sol.url}`,
  '',
  'Format 1: Hashnode Article (hashnodeArticle)',
  '- In-depth software architecture and systems engineering article in Markdown.',
  '- High technical depth, code snippets or architectural diagrams in ASCII/Mermaid where helpful.',
  `- Mentions SyaCo\'s solution: ${sol.url}`,
  '- Tags: 3 to 5 tags.',
  '',
  'Format 2: Manual Long-form Article (manualArticle)',
  '- Professional enterprise article in Thai suitable for tech blogs, media, or social platforms.',
  '- Clear business problem, technical solution, architectural benefits, and next steps.',
  `- Includes link: ${sol.url}`,
  '- Tags: 3 to 5 tags in Thai or English.',
  '',
  'Return valid JSON only matching the schema.'
].join('\n');

const geminiBodyB = {
  contents: [{ parts: [{ text: promptB }] }],
  generationConfig: {
    temperature: 0.7,
    responseMimeType: 'application/json',
    responseSchema: {
      type: 'OBJECT',
      properties: {
        hashnodeArticle: {
          type: 'OBJECT',
          properties: {
            title: { type: 'STRING' },
            bodyMarkdown: { type: 'STRING' },
            tags: { type: 'ARRAY', items: { type: 'STRING' } }
          },
          required: ['title', 'bodyMarkdown', 'tags']
        },
        manualArticle: {
          type: 'OBJECT',
          properties: {
            title: { type: 'STRING' },
            bodyMarkdown: { type: 'STRING' },
            tags: { type: 'ARRAY', items: { type: 'STRING' } }
          },
          required: ['title', 'bodyMarkdown', 'tags']
        }
      },
      required: ['hashnodeArticle', 'manualArticle']
    }
  }
};

return [{
  json: {
    solution: sol,
    geminiBodyA,
    geminiBodyB
  }
}];

const sol = $('Build AI Prompts for Call A & B').first().json.solution;

// 1. Parse Call A
const cA = $('Call Gemini AI (Micro & Dev.to)').first()?.json?.candidates || [];
const textA = cA[0]?.content?.parts?.[0]?.text || '{}';
let dataA = {};
try { dataA = JSON.parse(textA); } catch(e) {}

// 2. Parse Call B
const cB = $('Call Gemini AI (In-depth & Manual)').first()?.json?.candidates || [];
const textB = cB[0]?.content?.parts?.[0]?.text || '{}';
let dataB = {};
try { dataB = JSON.parse(textB); } catch(e) {}

// 3. Dev.to Tag Sanitizer
function sanitizeDevtoTags(rawTags) {
  return (rawTags || [])
    .map(t => String(t || '').toLowerCase().replace(/[^a-z0-9]/g, ''))
    .filter(t => t.length >= 2)
    .slice(0, 4);
}

const devtoTags = sanitizeDevtoTags(dataA.devtoArticle?.tags || ['tech', 'architecture']);
const hashnodeTags = (dataB.hashnodeArticle?.tags || ['tech', 'architecture']).slice(0, 5);
const manualTags = (dataB.manualArticle?.tags || ['tech', 'enterprise']).slice(0, 5);
const blueskyTags = ['syaco', 'tech'];

// 4. Bluesky Text & Facet
let blueskyText = String(dataA.blueskyPost || '').trim();
if (!blueskyText.includes(sol.url)) {
  blueskyText += ` ${sol.url}`;
}
if (blueskyText.length > 295) {
  const maxTxt = 295 - sol.url.length - 1;
  blueskyText = blueskyText.slice(0, maxTxt) + ' ' + sol.url;
}

return [{
  json: {
    solution_id: String(sol.id),
    solution_title: sol.titleEn || sol.titleTh,
    bluesky_title: (sol.titleTh || sol.titleEn).slice(0, 100),
    bluesky_content: blueskyText,
    bluesky_tags: blueskyTags,
    devto_title: String(dataA.devtoArticle?.title || sol.titleTh).trim(),
    devto_content: String(dataA.devtoArticle?.bodyMarkdown || sol.descTh).trim(),
    devto_tags: devtoTags,
    hashnode_title: String(dataB.hashnodeArticle?.title || sol.titleTh).trim(),
    hashnode_content: String(dataB.hashnodeArticle?.bodyMarkdown || sol.descTh).trim(),
    hashnode_tags: hashnodeTags,
    manual_title: String(dataB.manualArticle?.title || sol.titleTh).trim(),
    manual_content: String(dataB.manualArticle?.bodyMarkdown || sol.descTh).trim(),
    manual_tags: manualTags
  }
}];
